/* ================================================================== */
/*  DERIVED STATE HELPERS (no duplicated state — always computed)      */
/* ================================================================== */
function getProgram(id) {
  return PROGRAMS.find((p) => p.id === id);
}
function getAdventure(adventures, studentId, programId) {
  return adventures.find((a) => a.studentId === studentId && a.programId === programId);
}
function missionsDoneCount(adv) {
  return adv.missionsCompleted.filter((m) => m.done).length;
}
function missionsAllDone(adv) {
  return adv.missionsCompleted.length > 0 && adv.missionsCompleted.every((m) => m.done);
}
/** Single source of truth for an adventure's stage — never stored, always derived. */
function getStatus(adv) {
  if (adv.afterCompleted) return "completed";
  if (adv.attended) return "reflection_pending";
  if (adv.beforeCompleted) return "ready";
  return "registered";
}
function stageState(adv, program) {
  const before = adv.beforeCompleted ? "done" : "available";
  const trip = !program.dateReached ? "locked" : adv.attended ? "done" : "available";
  const after = !adv.attended ? "locked" : adv.afterCompleted ? "done" : "available";
  return { before, trip, after };
}
function attendedCount(adventures, studentId) {
  return adventures.filter((a) => a.studentId === studentId && a.attended).length;
}
const POINTS_PER_ADVENTURE = 20;
function carrotPoints(adventures, studentId) {
  return adventures.filter((a) => a.studentId === studentId && a.afterCompleted).length * POINTS_PER_ADVENTURE;
}

const STAMP_CARD_SIZE = 10;
const RANKS = [
  { min: 0, label: "Sprout", emoji: "🌱" },
  { min: 10, label: "Scout", emoji: "📙" },
  { min: 20, label: "Explorer", emoji: "🧭" },
  { min: 30, label: "Trailblazer", emoji: "🏅" },
  { min: 40, label: "Master", emoji: "👑" },
];
function rankFor(count) {
  const idx = RANKS.reduce((best, r, i) => (count >= r.min ? i : best), 0);
  const rank = RANKS[idx];
  const nextRank = RANKS[idx + 1];
  const pct = nextRank ? Math.min(100, Math.round(((count - rank.min) / (nextRank.min - rank.min)) * 100)) : 100;
  return { rank, nextRank, pct };
}

/** Badge criteria — each check runs against a student's own adventures. No hard-coded "earned". */
const BADGE_DEFS = [
  { id: "first", name: "First Adventure", emoji: "🥕", check: (advs) => advs.some((a) => a.afterCompleted) },
  { id: "museum", name: "Museum Explorer", emoji: "🏛️", check: (advs) => advs.some((a) => a.afterCompleted && getProgram(a.programId).isMuseum) },
  { id: "science", name: "Science Explorer", emoji: "🔬", check: (advs) => advs.some((a) => a.afterCompleted && getProgram(a.programId).category === "science") },
  { id: "nature", name: "Nature Explorer", emoji: "🌿", check: (advs) => advs.some((a) => a.afterCompleted && getProgram(a.programId).category === "nature") },
  { id: "history", name: "History Explorer", emoji: "🛡️", check: (advs) => advs.some((a) => a.afterCompleted && getProgram(a.programId).category === "history") },
  {
    id: "word",
    name: "Word Explorer",
    emoji: "⭐",
    // perfect score on the review quiz (or the old challenge quiz), or every word practiced 5 times
    check: (advs) =>
      advs.some((a) => {
        const sc = a.reviewScore || a.challengeScore;
        if (sc && sc.total > 0 && sc.correct === sc.total) return true;
        const words = getProgram(a.programId)?.vocabulary || [];
        return words.length > 0 && !!a.insights && words.every((w) => (a.insights.wordChecks?.[w.id] || 0) >= WORD_PRACTICE_GOAL);
      }),
  },
  { id: "curious", name: "Curious Thinker", emoji: "💡", check: (advs) => advs.filter((a) => a.bigQuestionCustom).length >= 2 },
  { id: "photographer", name: "Adventure Photographer", emoji: "📷", check: (advs) => advs.some((a) => a.reflection?.photo) },
  { id: "missionmaster", name: "Mission Master", emoji: "🧭", check: (advs) => advs.filter((a) => missionsAllDone(a)).length >= 2 },
  { id: "stamp10", name: "도장판 완성 (10회)", emoji: "🎟️", check: (advs) => advs.filter((a) => a.attended).length >= 10 },
  { id: "stamp20", name: "도장판 완성 (20회)", emoji: "🥉", check: (advs) => advs.filter((a) => a.attended).length >= 20 },
  { id: "stamp30", name: "도장판 완성 (30회)", emoji: "🥈", check: (advs) => advs.filter((a) => a.attended).length >= 30 },
  { id: "stamp40", name: "도장판 완성 (40회)", emoji: "🥇", check: (advs) => advs.filter((a) => a.attended).length >= 40 },
  { id: "stamp50", name: "도장판 완성 (50회)", emoji: "🏆", check: (advs) => advs.filter((a) => a.attended).length >= 50 },
];
function computeBadges(adventures, studentId) {
  const mine = adventures.filter((a) => a.studentId === studentId);
  return BADGE_DEFS.map((b) => ({ ...b, earned: b.check(mine) }));
}

function speak(word) {
  try {
    const u = new SpeechSynthesisUtterance(word);
    u.lang = "en-US";
    u.rate = 0.85;
    window.speechSynthesis.cancel();
    window.speechSynthesis.speak(u);
  } catch (e) {
    /* speech synthesis unavailable — fail silently, it's a nice-to-have */
  }
}
function readFileAsDataUrl(file, cb) {
  try {
    const reader = new FileReader();
    reader.onload = () => cb(reader.result);
    reader.onerror = () => console.warn("Could not read the selected photo.");
    reader.readAsDataURL(file);
  } catch (e) {
    console.warn("Photo upload failed", e);
  }
}

