function StageProgress({ before, trip, after, current, onPick, labels }) {
  const stages = [
    { key: "before", label: labels?.before ?? "Get Ready", state: before },
    { key: "trip", label: labels?.trip ?? "Explore", state: trip },
    { key: "after", label: labels?.after ?? "Review", state: after },
  ];
  return (
    <div className="relative flex items-center justify-between px-2">
      <div className="absolute left-6 right-6 top-4 h-0.5" style={{ background: C.beige, width: "calc(100% - 3rem)" }} />
      {stages.map((s) => (
        <button
          key={s.key}
          onClick={() => onPick && s.state !== "locked" && onPick(s.key)}
          className="focus-ring relative z-10 flex flex-col items-center gap-1.5 f-body"
          disabled={!onPick || s.state === "locked"}
          aria-current={current === s.key ? "step" : undefined}
        >
          <StageDot state={current === s.key ? (s.state === "locked" ? "locked" : "active") : s.state} />
          <span className="text-[11px] font-bold" style={{ color: current === s.key ? C.green : "#9C927D" }}>
            {s.label}
          </span>
        </button>
      ))}
    </div>
  );
}

/** Slim three-part switcher used inside an adventure (replaces the big circles + banner). */
function StageTabs({ before, trip, after, current, onPick }) {
  const stages = [
    { key: "before", label: "Get Ready", state: before },
    { key: "trip", label: "Explore", state: trip },
    { key: "after", label: "Review", state: after },
  ];
  return (
    <div className="flex gap-1 p-1 rounded-full" style={{ background: C.beige }} role="tablist">
      {stages.map((st) => {
        const active = current === st.key;
        const locked = st.state === "locked";
        return (
          <button
            key={st.key}
            role="tab"
            aria-selected={active}
            onClick={() => !locked && onPick(st.key)}
            disabled={locked}
            className="focus-ring tap flex-1 f-body text-[12px] font-bold rounded-full py-1.5 flex items-center justify-center gap-1"
            style={{ background: active ? "white" : "transparent", color: active ? C.green : "#9C927D" }}
          >
            {st.state === "done" && <Check size={12} strokeWidth={3} />}
            {locked && <Lock size={11} />}
            {st.label}
          </button>
        );
      })}
    </div>
  );
}

