function SplashScreen({ onDone }) {
  const [closing, setClosing] = useState(false);
  const [active, setActive] = useState(0);
  const SLIDE_MS = 1150;

  useEffect(() => {
    const t = setInterval(() => setActive((i) => (i + 1) % SPLASH_SLIDES.length), SLIDE_MS);
    return () => clearInterval(t);
  }, []);

  useEffect(() => {
    const t = setTimeout(() => setClosing(true), SLIDE_MS * SPLASH_SLIDES.length + 200);
    return () => clearTimeout(t);
  }, []);

  useEffect(() => {
    if (!closing) return;
    const t = setTimeout(onDone, 350);
    return () => clearTimeout(t);
  }, [closing]);

  return (
    <div
      onClick={onDone}
      className={`fixed inset-0 z-50 flex justify-center transition-opacity duration-300 ${closing ? "opacity-0" : "opacity-100"}`}
      style={{ background: C.cream }}
    >
      <div className="relative w-full max-w-md h-full flex flex-col items-center justify-center overflow-hidden px-8">
        <svg width="44" height="44" viewBox="0 0 76 76" fill="none" className="mb-3">
          <circle cx="38" cy="38" r="32" stroke={C.green} strokeWidth="1.4" opacity="0.85" />
          <line x1="38" y1="6" x2="38" y2="12" stroke={C.green} strokeWidth="1.4" />
          <line x1="70" y1="38" x2="64" y2="38" stroke={C.green} strokeWidth="1.2" opacity="0.5" />
          <line x1="38" y1="70" x2="38" y2="64" stroke={C.green} strokeWidth="1.2" opacity="0.5" />
          <line x1="6" y1="38" x2="12" y2="38" stroke={C.green} strokeWidth="1.2" opacity="0.5" />
          <g className="needle-spin">
            <path d="M31,33 Q37,34 38,40 Q39,34 45,33 Q40,42 38,56 Q36,42 31,33 Z" fill={C.orange} stroke={C.green} strokeWidth="1" />
            <circle cx="38" cy="39" r="2" fill={C.cream} />
            <path d="M38,33 C36,29 36,25 37,22" stroke={C.green} strokeWidth="1.4" fill="none" strokeLinecap="round" />
            <path d="M38,33 C39,28 41,25 44,23" stroke={C.green} strokeWidth="1.4" fill="none" strokeLinecap="round" />
            <path d="M38,33 C37,28 35,25 32,23" stroke={C.green} strokeWidth="1.4" fill="none" strokeLinecap="round" />
          </g>
        </svg>

        <p className="f-display text-[19px] font-bold mb-1 rise-in" style={{ color: C.green, letterSpacing: "0.1em" }}>
          CARROTWORLD
        </p>
        <p className="f-body text-[10px] uppercase mb-6 rise-in" style={{ color: C.green, letterSpacing: "0.18em" }}>
          Experience <span style={{ color: C.orange }}>•</span> Explore <span style={{ color: C.orange }}>•</span> Express
        </p>

        <div className="relative w-full rounded-2xl overflow-hidden mb-3 mx-auto" style={{ maxWidth: 260, aspectRatio: "1 / 1", boxShadow: "0 8px 24px rgba(23,76,53,0.14)" }}>
          {SPLASH_SLIDES.map((src, i) => (
            <img
              key={i}
              src={src}
              alt=""
              className={i === active ? `slide-active-${i % 3}` : ""}
              style={{
                position: "absolute",
                inset: 0,
                width: "100%",
                height: "100%",
                objectFit: "cover",
                opacity: i === active ? 1 : 0,
                transition: "opacity 0.6s ease",
              }}
            />
          ))}
        </div>

        <div className="flex items-center gap-1.5 mb-6">
          {SPLASH_SLIDES.map((_, i) => (
            <span
              key={i}
              className="rounded-full transition-all"
              style={{
                width: i === active ? 16 : 6,
                height: 6,
                background: i === active ? C.orange : C.beige,
              }}
            />
          ))}
        </div>

        <p className="f-body text-[13px] text-center rise-in" style={{ color: "#5C7A6B" }}>
          아이의 특별한 하루를 기록합니다
        </p>
      </div>
    </div>
  );
}
